 // Unset/1 = original timing (integer division by 1 is exact).
 const int64_t time_scale=[]{const char* v=std::getenv("J2ME_REPRO_TIME_SCALE");int k=v?std::atoi(v):1;return int64_t(k>0?k:1);}();
